begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users (id,email) values ('94000000-0000-0000-0000-000000000001','invoice-review-owner@example.invalid'),('94000000-0000-0000-0000-000000000002','invoice-review-employee@example.invalid');
insert into businesses (id,name,updated_at) overriding system value values (-94001,'Invoice business','2026-01-01');
insert into business_members (business_id,user_id,role,active) values (-94001,'94000000-0000-0000-0000-000000000001','owner',true),(-94001,'94000000-0000-0000-0000-000000000002','employee',true);
insert into customers (id,business_id,first_name,last_name,updated_at) overriding system value values (-94001,-94001,'Original','Customer','2026-01-01');
insert into jobs (id,business_id,customer_id,work_description,service_address,status,updated_at) overriding system value values (-94001,-94001,-94001,'Original work','1 Main St','completed','2026-01-01');
insert into invoices (id,business_id,customer_id,job_id,invoice_number,amount,invoice_date,due_date,payment_terms,status,updated_at) overriding system value values (-94001,-94001,-94001,-94001,'INV-2026-0001-01',300,'2026-09-25','2026-10-01','Due on receipt','unpaid','2026-01-01');
set local role authenticated;
set local request.jwt.claim.sub = '94000000-0000-0000-0000-000000000001';
select lives_ok($test$select save_invoice_pdf_review(-94001,-94001,'2026-01-01','2026-01-01','2026-01-01','{"invoice_date":"2026-09-26","due_date":"2026-10-10","amount":425.99,"payment_terms":"Net 15","pdf_description":"Updated work","pdf_service_address":"2 Oak Lane","pdf_message":"Thank you for choosing us.","pdf_notes":"Keep this receipt."}','{"first_name":"Updated"}','{"name":"Updated Business"}')$test$,'owner saves invoice review atomically');
select is((select invoice_number from invoices where id=-94001),'INV-2026-0001-01','invoice number remains unchanged');
select ok((select amount=425.99 and pdf_description='Updated work' and pdf_service_address='2 Oak Lane' and pdf_message='Thank you for choosing us.' and pdf_notes='Keep this receipt.' from invoices where id=-94001),'invoice PDF fields saved');
select is((select first_name from customers where id=-94001),'Updated','customer edit saved');
select is((select name from businesses where id=-94001),'Updated Business','business edit saved');
set local request.jwt.claim.sub = '94000000-0000-0000-0000-000000000002';
select is(private.is_business_admin(-94001), false, 'employee is not a business admin');
select throws_ok($test$select save_invoice_pdf_review(-94001,-94001,(select updated_at from invoices where id=-94001),(select updated_at from customers where id=-94001),(select updated_at from businesses where id=-94001),'{"invoice_date":"2026-09-26","due_date":"2026-10-10","amount":425.99,"pdf_message":"Employee attempt"}','{}','{"name":"Employee attempt"}')$test$,'42501',null,'employee cannot edit business details');
select throws_ok($test$select save_invoice_pdf_review(-94001,-94001,'2026-01-01','2026-01-01','2026-01-01','{"invoice_date":"2026-09-26","amount":425.99,"pdf_message":"Stale"}','{}','{}')$test$,'40001',null,'stale invoice review rejected');
select throws_ok($test$select save_invoice_pdf_review(-94001,-94001,(select updated_at from invoices where id=-94001),(select updated_at from customers where id=-94001),(select updated_at from businesses where id=-94001),'{"invoice_date":"2026-09-26","due_date":"2026-09-25","amount":425.99,"pdf_message":"Bad date"}','{}','{}')$test$,'23514',null,'invalid due date rejected');
select has_function_privilege('anon','public.save_invoice_pdf_review(bigint,bigint,timestamptz,timestamptz,timestamptz,jsonb,jsonb,jsonb)','execute') is false as "anonymous execution denied";
select ok((select not prosecdef from pg_proc where oid='public.save_invoice_pdf_review(bigint,bigint,timestamptz,timestamptz,timestamptz,jsonb,jsonb,jsonb)'::regprocedure),'function retains caller privileges');
select * from finish();
rollback;
